export default {async fetch(request,env){const url=new URL(request.url);if(url.pathname.startsWith('/api/mentor'))return handleMentor(request,env);if(request.method!=='GET'&&request.method!=='HEAD')return new Response('Method not allowed',{status:405});if(url.pathname==='/favicon.ico')return new Response(null,{status:204});if(request.method==='GET'&&url.pathname.startsWith('/linux/'))return fetchLinuxAsset(url.pathname.slice(7),...diskCache);const html=url.pathname==='/'||url.pathname==='/index.html'?PAGE_HTML:url.pathname==='/computer.html'?MODEL_HTML:null;if(html===null)return new Response('Not found',{status:404});return new Response(request.method==='HEAD'?null:html,{headers:{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});}};
